function commandCenter(){const c=state.colony;const progression=state.progression;const resourceTiles=Object.entries(state.resources).map(([key,value])=>'<div class="resource-tile"><small>'+esc(key.replace('_',' '))+'</small><strong>'+fmt(value)+'</strong><div class="bar"><i style="width:'+Math.min(100,Math.max(10,Math.round(Number(value)/12400)))+'%"></i></div></div>').join('');const queues=state.queues.map(q=>'<div class="row"><div><strong>'+esc(q.name)+'</strong><small>'+esc(q.kind)+' · '+esc(q.level)+' · '+esc(q.status)+'</small></div><span class="badge">'+esc(q.remaining)+'</span></div>').join('');const missions=state.missions.map(m=>'<div class="row"><div><strong>'+esc(m.type)+'</strong><small>'+esc(m.target)+' · '+esc(m.status)+'</small></div><span class="badge">'+esc(m.eta)+'</span></div>').join('');const buildings=state.buildings.map(b=>'<tr><td>'+esc(b.name)+'</td><td>Level '+b.level+'</td><td>'+esc(b.output)+'</td><td><span class="badge good">'+esc(b.state)+'</span></td></tr>').join('');const alerts=state.alerts.map(a=>'<div class="alert"><strong class="'+esc(a.level)+'">'+esc(a.title)+'</strong><span>'+esc(a.detail)+'</span></div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Command Center';document.getElementById('description').textContent='Server-authoritative colony operations, life support, queues, fleet movement, and turn settlement in one game dashboard.';document.getElementById('content').innerHTML='<div class="resource-strip">'+resourceTiles+'</div><div class="cc-grid"><div class="card wide"><div class="eyebrow">COLONY OVERVIEW</div><h2>'+esc(c.name)+' <span class="badge">'+esc(c.coordinate)+'</span></h2><div class="metric-grid"><div class="metric"><span>Population</span><strong>'+fmt(c.population)+' / '+fmt(c.capacity)+'</strong><small>Capacity utilization '+Math.round(c.population/c.capacity*100)+'%</small></div><div class="metric"><span>Morale</span><strong>'+c.morale+'%</strong><small>Stable colony confidence</small></div><div class="metric"><span>Life support</span><strong>'+fmt(c.food)+' / '+fmt(c.water)+'</strong><small>Food / Water reserves</small></div></div><div class="feedback" style="display:block">State loaded from <b>players</b>, <b>player_resources</b>, <b>player_colonies</b>, <b>rankings</b>, and <b>game_events</b>.</div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS</div><h2>Command controls</h2><div class="actions"><div class="action"><span>Process next turn</span>'+actionButton('process_turns','Process turns','dark')+'</div><div class="action"><span>Open target board</span>'+actionButton('choose_target','Choose target')+'</div><div class="action"><span>Read command reports</span>'+actionButton('review_reports','Review reports')+'</div></div><div class="permission">Authenticated commander · CSRF required · RBAC checked · ownership validated · transaction committed server-side.</div><div id="feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">CONSTRUCTION / RESEARCH / SHIPYARD</div><h2>Active queues</h2>'+queues+'</div><div class="card side-card"><div class="eyebrow">LIFE SUPPORT</div><h2>Colony systems</h2><div class="row"><div><strong>Food</strong><small>'+c.food_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Water</strong><small>'+c.water_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Morale</strong><small>Population stability</small></div><span class="badge good">'+c.morale+'%</span></div>'+actionButton('open_colony','Open colony')+'</div><div class="card wide"><div class="eyebrow">BUILDING STATUS</div><h2>Colony infrastructure</h2><table class="table"><thead><tr><th>Building</th><th>Level</th><th>Output</th><th>State</th></tr></thead><tbody>'+buildings+'</tbody></table></div><div class="card side-card"><div class="eyebrow">FLEET CONTROL</div><h2>Mission board</h2>'+missions+actionButton('dispatch_fleet','Dispatch fleet')+'</div><div class="card wide"><div class="eyebrow">UNIVERSAL PROGRESSION</div><h2>Tier '+progression.tier+' / Level '+progression.level+' <span class="badge">'+esc(progression.tier_name)+'</span></h2><div class="metric-grid"><div class="metric"><span>Global level</span><strong>'+progression.global_level+' / 483</strong><small>21 tiers × 23 levels</small></div><div class="metric"><span>Next level</span><strong>'+progression.next_level+'</strong><small>'+progression.progress_percent+'% progress</small></div><div class="metric"><span>Current effect</span><strong>+'+progression.effect_percent.toFixed(1)+'%</strong><small>Player progression modifier</small></div></div><div class="bar"><i style="width:'+progression.progress_percent+'%"></i></div><div class="actions" style="margin-top:12px">'+actionButton('progression_advance','Advance player level','dark')+' <span class="badge">Server validates cost, prerequisites, and tier cap</span></div></div><div class="card wide"><div class="eyebrow">COMMAND ALERTS</div><h2>Events and warnings</h2>'+alerts+'</div><div class="card side-card"><div class="eyebrow">PAGE CONTRACT</div><h2>Dashboard / dashboard</h2><p class="permission">The browser submits player intent only. `process_turns` calls the PHP service layer, settles resources and queues in a transaction, writes an event, and returns refreshed state.</p><span class="badge">process_turns</span> <span class="badge">players</span> <span class="badge">player_resources</span> <span class="badge">rankings</span> <span class="badge">game_events</span></div></div>';document.querySelectorAll('.server-action').forEach(b=>b.onclick=()=>{const f=document.getElementById('feedback');f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → POST actions/game.php → permission check → transaction → refreshed dashboard state.'})}
function accountInfo(){const a=state.account||{commander:'Tanang',username:'tanang',race:"Tau'ri",government:'Stellar Republic',rank:'Commander',level:12,glory:1840,reputation:920,experience:72800,victories:38,defeats:7,protection:'Active',vacation:'Off',registration:'Complete',created:'2026-01-14',lastLogin:'Current session'};document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Account Information';document.getElementById('description').textContent='Commander identity, faction bonuses, progression, protection, and account security are read from authenticated server state.';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COMMANDER PROFILE</div><h2>'+esc(a.commander)+' <span class="badge good">AUTHENTICATED</span></h2><div class="metric-grid"><div class="metric"><span>Username</span><strong>'+esc(a.username)+'</strong><small>Account handle</small></div><div class="metric"><span>Rank</span><strong>'+esc(a.rank)+'</strong><small>Level '+fmt(a.level)+'</small></div><div class="metric"><span>Registration</span><strong>'+esc(a.registration)+'</strong><small>Created '+esc(a.created)+'</small></div></div></div><div class="card side-card"><div class="eyebrow">FACTION IDENTITY</div><h2>'+esc(a.race)+'</h2><div class="row"><div><strong>Government</strong><small>Current political system</small></div><span class="badge">'+esc(a.government)+'</span></div><div class="row"><div><strong>Combined modifiers</strong><small>Race × government</small></div><span class="badge good">APPLIED</span></div><button class="button dark" onclick="openPage(\'race\')">Review faction bonuses</button></div><div class="card wide"><div class="eyebrow">PROGRESSION</div><h2>Glory, Reputation, and experience</h2><div class="metric-grid"><div class="metric"><span>Experience</span><strong>'+fmt(a.experience)+'</strong><small>Level '+fmt(a.level)+' progression</small><div class="bar"><i style="width:72%"></i></div></div><div class="metric"><span>Glory</span><strong>'+fmt(a.glory)+'</strong><small>Ascension resource</small></div><div class="metric"><span>Reputation</span><strong>'+fmt(a.reputation)+'</strong><small>Diplomacy and rank</small></div></div><div class="row"><span>Victories / defeats</span><strong>'+fmt(a.victories)+' / '+fmt(a.defeats)+'</strong></div></div><div class="card side-card"><div class="eyebrow">PROTECTION</div><h2>Account safeguards</h2><div class="row"><div><strong>Protection status</strong><small>Combat eligibility</small></div><span class="badge good">'+esc(a.protection)+'</span></div><div class="row"><div><strong>Vacation mode</strong><small>Long-term protection</small></div><span class="badge">'+esc(a.vacation)+'</span></div><button class="button" onclick="openPage(\'vacation\')">Manage vacation mode</button></div><div class="card wide"><div class="eyebrow">SECURITY AND SESSION</div><h2>Authenticated account state</h2><div class="row"><span>Last login</span><strong>'+esc(a.lastLogin)+'</strong></div><div class="row"><span>Session protection</span><span class="badge good">CSRF + RBAC ENABLED</span></div><div class="row"><span>Data authority</span><span class="badge good">SERVER-SIDE PDO</span></div><p class="permission">Read-only account data is scoped to the authenticated commander. Race changes, government reform, vacation, and ascension use separate CSRF-protected PHP actions.</p></div><div class="card side-card"><div class="eyebrow">ACCOUNT CONTROLS</div><h2>Sub-pages</h2><div class="actions"><button class="button" onclick="openPage(\'race\')">Race and government</button><button class="button" onclick="openPage(\'ascension\')">Progression and ascension</button><button class="button" onclick="openPage(\'messages\')">Account messages</button></div><div class="feedback" style="display:block">State loaded from players, races, governments, rankings, progression, glory, protection, and audit records.</div></div></div>'}function openPage(page){selected=page;render()}function genericPage(){const p=all.find(x=>x.key===selected)||all[0],d=details[p.layout]||{hero:p.title,panels:['Overview','Controls','Activity'],formula:'Validated server-side state transition',controls:p.controls||[],action:(p.actions||[])[0]||null,tables:p.tables||[],permission:'authenticated commander',states:['ready','empty','error']},ic=interactions[p.layout]||{page:p.title,purpose:d.hero,buttons:{}};document.getElementById('section').textContent=(p.group||'SYSTEM').toUpperCase();document.getElementById('title').textContent=p.title;document.getElementById('description').textContent=d.hero+' — '+d.formula;const panels=(d.panels||[]).map((x,i)=>'<div class="row"><div><strong>'+esc(x)+'</strong><small>'+esc(d.formula)+'</small></div><span class="badge">STATE '+(i+1)+'</span></div>').join('');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>'+esc(d.hero)+'</h2>'+panels+'</div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2>'+(Object.entries(ic.buttons||{}).map(([label,b])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(b.logic)+'</small></div><span class="badge">'+esc(b.action)+'</span></div>').join('')||'<div class="empty">Read-only information view</div>')+'<p class="permission">'+esc(d.permission)+'</p></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: <b>'+esc(d.action||((p.actions||[]).join(', ')||'read-only'))+'</b></p>'+((d.tables||p.tables||[]).map(x=>'<span class="badge">'+esc(x)+'</span> ').join(''))+'<p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+((d.states||[]).map(x=>'<div class="row"><span>'+esc(x)+'</span><span class="badge">HANDLED</span></div>').join(''))+'</div></div>'}
